@stereotype(CIMStereotype.GridAPPSD)
@stereotype(CIMStereotype.enumeration)
@stereotype(CIMStereotype.Attribute)
class TransformerCoreMaterialKind(Enum):
    '''
    Classification of the primary ferromagnetic material used in the fabrication
    of a transformer magnetic core
    '''

    amorphousSteel = 'amorphousSteel'
    '''
    A non-crystalline alloy with a disordered atomic structure, providing
    low core (no-load) losses
    '''
    
    grainOrientedSteel = 'grainOrientedSteel'
    '''
    Cold-rolled electrical steel with uniform crystal orientation, optimizing
    magnetic permeability along the direction of the flux path
    '''
    
    nanoCrystallineAlloy = 'nanoCrystallineAlloy'
    '''
    An advanced material with a nanometer-scale grain structure, combining
    exceptionally high magnetic permeability with negligible core losses
    '''
    
    nonGrainOrientedSteel = 'nonGrainOrientedSteel'
    '''
    Isotropic electrical steel with uniform magnetic properties in all
    directions, often used where flux paths are complex or rotating
    '''
    
    solidIron = 'solidIron'
    '''
    Unlaminated magnetic iron, primarily used in older transformers, specialized
    DC applications, or shielding due to high eddy current losses under
    AC conditions
    '''
    
    @property
    def __namespace__(self):
        return 'http://gridappsd.org/CIM/extension#'
    @property
    def __package__(self):
        return 'AssetInfoEXT'
    @property
    def __minOccurs__(self):
        return '0'
    @property
    def __maxOccurs__(self):
        return 'unbounded'
    
