    '''
    
    ToTransformerWinding: Optional[TransformerWinding] = field(
        default=None,
        metadata={
        'type': 'Association',
        'stereotypes': ['new'],
        'minOccurs': '0',
        'maxOccurs': '1',
        'inverse': 'TransformerWinding.ToTransformerLug',
        'namespace': 'http://cim.ucaiug.io/cim101/draft#',
        'serialize': True,
        })
    '''
